mapper.select:
SELECT id, workspace_id AS workspaceId, entity_type AS entityType,
       entity_id AS entityId, file_name AS fileName, content_type AS contentType, url
FROM attachment
WHERE workspace_id = #{workspaceId}
  AND id > #{afterId}
  AND url LIKE '/attachments/%'
ORDER BY id
LIMIT #{limit}

SELECT id, workspace_id AS workspaceId, image_url AS url
FROM person
WHERE workspace_id = #{workspaceId}
  AND id > #{afterId}
  AND image_url LIKE '/contact-pictures/%'
ORDER BY id
LIMIT #{limit}

SELECT id, workspace_id AS workspaceId, logo_url AS url
FROM company
WHERE workspace_id = #{workspaceId}
  AND id > #{afterId}
  AND logo_url LIKE '/company-logos/%'
ORDER BY id
LIMIT #{limit}

mapper.update:
UPDATE attachment
SET url = #{newUrl}, file_name = #{fileName}, content_type = #{contentType}, size = #{size}
WHERE workspace_id = #{workspaceId} AND id = #{id} AND url <=> #{currentUrl}

UPDATE person
SET image_url = #{newUrl}
WHERE workspace_id = #{workspaceId} AND id = #{id} AND image_url <=> #{currentUrl}

UPDATE company
SET logo_url = #{newUrl}
WHERE workspace_id = #{workspaceId} AND id = #{id} AND logo_url <=> #{currentUrl}
